// Package plugin implements the gh-style plugin system: external executables
// named `entire-<name>` that the CLI discovers and dispatches to when an
// unknown subcommand is invoked.
//
// See docs/plugin-system-plan.md for the architecture, and gh's
// pkg/cmd/extension for the design we mirror.
package plugin

import (
	"fmt"
	"os"

	"gopkg.in/yaml.v3"
)

// ManifestFileName is the filename of the binary plugin manifest within a
// plugin directory. Field-for-field parity with gh's binManifest.
const ManifestFileName = "manifest.yml"

// BinaryManifest describes a plugin installed from a GitHub release asset.
// Field-for-field parity with gh's binManifest so user intuition transfers.
type BinaryManifest struct {
	Owner    string `yaml:"owner"`
	Name     string `yaml:"name"`
	Host     string `yaml:"host"`
	Tag      string `yaml:"tag"`
	IsPinned bool   `yaml:"isPinned"`
	Path     string `yaml:"path"`
}

// LoadBinaryManifest reads a manifest from disk.
func LoadBinaryManifest(path string) (*BinaryManifest, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read manifest: %w", err)
	}
	var m BinaryManifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("parse manifest: %w", err)
	}
	return &m, nil
}

// Save writes the manifest to disk at path.
func (m *BinaryManifest) Save(path string) error {
	data, err := yaml.Marshal(m)
	if err != nil {
		return fmt.Errorf("encode manifest: %w", err)
	}
	if err := os.WriteFile(path, data, 0o600); err != nil {
		return fmt.Errorf("write manifest: %w", err)
	}
	return nil
}

package plugin

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
)

// Prefix is the required filename prefix for plugin executables and their
// containing directories. `entire <name>` dispatches to `entire-<name>`.
const Prefix = "entire-"

// Kind classifies how a plugin was installed.
type Kind string

const (
	// KindBinary is a plugin installed from a GitHub release asset. Has a
	// manifest.yml describing owner/name/tag.
	KindBinary Kind = "binary"
	// KindScript is a git-cloned repository whose root contains an executable
	// of the same name as the directory.
	KindScript Kind = "script"
	// KindLocal is a symlink, used by `entire plugin install .` for development.
	KindLocal Kind = "local"
)

// Plugin describes one installed plugin.
type Plugin struct {
	// Name is the bare plugin name (without the "entire-" prefix).
	Name string
	// Kind is how this plugin was installed.
	Kind Kind
	// Dir is the absolute path to the plugin directory inside the plugins
	// root. For local plugins, this is the symlink path itself.
	Dir string
	// ExecPath is the absolute path to the executable to invoke.
	ExecPath string
	// Manifest is populated for binary plugins. Nil otherwise.
	Manifest *BinaryManifest
	// PinnedSHA is the sha recorded in a .pin-<sha> marker, empty if unpinned.
	PinnedSHA string
}

// FullName returns the executable name including the "entire-" prefix.
func (p *Plugin) FullName() string {
	return Prefix + p.Name
}

// Manager handles plugin storage discovery and lifecycle.
type Manager struct {
	// Root is the plugins directory (e.g. ~/.local/share/entire/plugins).
	Root string
}

// NewManager returns a manager rooted at the configured plugins directory.
// Honors ENTIRE_PLUGIN_DIR; falls back to XDG_DATA_HOME/entire/plugins, then
// to a platform default.
func NewManager() (*Manager, error) {
	root, err := DefaultRoot()
	if err != nil {
		return nil, err
	}
	return &Manager{Root: root}, nil
}

// DefaultRoot resolves the plugins directory.
func DefaultRoot() (string, error) {
	if v := os.Getenv("ENTIRE_PLUGIN_DIR"); v != "" {
		return v, nil
	}
	if v := os.Getenv("XDG_DATA_HOME"); v != "" {
		return filepath.Join(v, "entire", "plugins"), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("resolve home dir: %w", err)
	}
	switch runtime.GOOS {
	case "windows":
		if appData := os.Getenv("LOCALAPPDATA"); appData != "" {
			return filepath.Join(appData, "entire", "plugins"), nil
		}
		return filepath.Join(home, "AppData", "Local", "entire", "plugins"), nil
	case "darwin":
		// Match XDG convention even on macOS for consistency with gh.
		return filepath.Join(home, ".local", "share", "entire", "plugins"), nil
	default:
		return filepath.Join(home, ".local", "share", "entire", "plugins"), nil
	}
}

// EnsureRoot creates the plugins directory if it does not exist.
func (m *Manager) EnsureRoot() error {
	if err := os.MkdirAll(m.Root, 0o755); err != nil {
		return fmt.Errorf("create plugin dir: %w", err)
	}
	return nil
}

// List returns all plugins discovered under Root, sorted by name.
// Entries that don't follow the entire-<name> naming or aren't classifiable
// are skipped silently.
func (m *Manager) List() ([]*Plugin, error) {
	entries, err := os.ReadDir(m.Root)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read plugin dir: %w", err)
	}

	var plugins []*Plugin
	for _, e := range entries {
		name := e.Name()
		if !strings.HasPrefix(name, Prefix) {
			continue
		}
		p, err := m.classify(name)
		if err != nil || p == nil {
			continue
		}
		plugins = append(plugins, p)
	}

	sort.Slice(plugins, func(i, j int) bool { return plugins[i].Name < plugins[j].Name })
	return plugins, nil
}

// Find returns the plugin with the given bare name (without the "entire-"
// prefix), or nil if none is installed.
func (m *Manager) Find(name string) (*Plugin, error) {
	if name == "" {
		return nil, nil
	}
	full := Prefix + name
	p, err := m.classify(full)
	if err != nil {
		return nil, err
	}
	return p, nil
}

// classify inspects a single entry name (e.g. "entire-foo") under Root and
// returns the corresponding Plugin or nil if it isn't a valid plugin.
func (m *Manager) classify(fullName string) (*Plugin, error) {
	if !strings.HasPrefix(fullName, Prefix) {
		return nil, nil
	}
	bare := strings.TrimPrefix(fullName, Prefix)
	if bare == "" {
		return nil, nil
	}

	path := filepath.Join(m.Root, fullName)
	info, err := os.Lstat(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("stat plugin %q: %w", fullName, err)
	}

	// Symlink → local plugin.
	if info.Mode()&os.ModeSymlink != 0 {
		target, err := filepath.EvalSymlinks(path)
		if err != nil {
			return nil, fmt.Errorf("resolve local plugin symlink %q: %w", fullName, err)
		}
		exec := localExecPath(target, fullName)
		return &Plugin{
			Name:     bare,
			Kind:     KindLocal,
			Dir:      path,
			ExecPath: exec,
		}, nil
	}

	// Regular file at root level isn't a valid plugin layout.
	if !info.IsDir() {
		return nil, nil
	}

	// Manifest present → binary plugin.
	manifestPath := filepath.Join(path, ManifestFileName)
	if _, err := os.Stat(manifestPath); err == nil {
		mf, err := LoadBinaryManifest(manifestPath)
		if err != nil {
			return nil, err
		}
		exec := mf.Path
		if exec == "" {
			exec = filepath.Join(path, executableName(fullName))
		}
		return &Plugin{
			Name:      bare,
			Kind:      KindBinary,
			Dir:       path,
			ExecPath:  exec,
			Manifest:  mf,
			PinnedSHA: readPinSHA(path),
		}, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, fmt.Errorf("stat manifest %q: %w", manifestPath, err)
	}

	// Otherwise → script plugin (must contain an executable matching the dir name).
	exec := filepath.Join(path, executableName(fullName))
	if _, err := os.Stat(exec); err != nil {
		return nil, nil
	}
	return &Plugin{
		Name:      bare,
		Kind:      KindScript,
		Dir:       path,
		ExecPath:  exec,
		PinnedSHA: readPinSHA(path),
	}, nil
}

// localExecPath returns the executable path for a local plugin given the
// resolved symlink target. The target is expected to be either the executable
// itself or a directory containing it.
func localExecPath(target, fullName string) string {
	info, err := os.Stat(target)
	if err == nil && info.IsDir() {
		return filepath.Join(target, executableName(fullName))
	}
	return target
}

// executableName returns the platform-specific executable filename inside a
// plugin directory.
func executableName(fullName string) string {
	if runtime.GOOS == "windows" {
		return fullName + ".exe"
	}
	return fullName
}

// ValidName reports whether s is a valid bare plugin name. Plugin names must
// be non-empty, lowercase ASCII letters, digits, and dashes. They must not
// start with a dash.
func ValidName(s string) bool {
	if s == "" || s[0] == '-' {
		return false
	}
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z':
		case r >= '0' && r <= '9':
		case r == '-':
		default:
			return false
		}
	}
	return true
}

package plugin

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
)

const pinPrefix = ".pin-"

// readPinSHA returns the pinned SHA from a .pin-<sha> marker in dir, or "" if
// none exists. The first matching file wins; multiple pins are not expected.
func readPinSHA(dir string) string {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return ""
	}
	for _, e := range entries {
		name := e.Name()
		if strings.HasPrefix(name, pinPrefix) {
			return strings.TrimPrefix(name, pinPrefix)
		}
	}
	return ""
}

// writePin creates a .pin-<sha> marker in dir, removing any previous marker.
// Empty sha clears the pin.
func writePin(dir, sha string) error {
	if err := clearPin(dir); err != nil {
		return err
	}
	if sha == "" {
		return nil
	}
	return os.WriteFile(filepath.Join(dir, pinPrefix+sha), nil, 0o644)
}

// clearPin removes any .pin-<sha> marker in dir.
func clearPin(dir string) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	for _, e := range entries {
		if strings.HasPrefix(e.Name(), pinPrefix) {
			if err := os.Remove(filepath.Join(dir, e.Name())); err != nil {
				return err
			}
		}
	}
	return nil
}

package plugin

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"

	"github.com/spf13/cobra"
)

// Dispatch resolves an unknown subcommand to an installed plugin and execs
// it. Returns handled=true if a plugin was found and executed (even if it
// returned a non-zero exit code, which is propagated via err). When handled
// is false, the caller should fall through to its normal unknown-command
// handling.
//
// args is the full argv slice excluding the program name (e.g.
// os.Args[1:]). Cobra resolves built-ins first, so any name registered on
// rootCmd (including aliases) takes precedence over an installed plugin.
func Dispatch(ctx context.Context, rootCmd *cobra.Command, args []string) (bool, error) {
	if len(args) == 0 {
		return false, nil
	}

	// Skip flags. The first non-flag arg is the candidate subcommand name.
	// We deliberately mirror cobra's "first positional after the root" model:
	// `entire --foo bar baz` → the candidate is "bar".
	first := -1
	for i, a := range args {
		if a == "--" {
			if i+1 < len(args) {
				first = i + 1
			}
			break
		}
		if len(a) == 0 || a[0] == '-' {
			continue
		}
		first = i
		break
	}
	if first == -1 {
		return false, nil
	}

	name := args[first]
	if !ValidName(name) {
		return false, nil
	}

	// Built-in precedence: cobra resolves built-ins first. If rootCmd.Find()
	// returns a non-root command, the user wanted a built-in (potentially
	// misspelled) and we should not shadow it.
	if isBuiltin(rootCmd, name) {
		return false, nil
	}

	mgr, err := NewManager()
	if err != nil {
		return false, err
	}
	p, err := mgr.Find(name)
	if err != nil {
		return false, err
	}
	if p == nil {
		return false, nil
	}

	rest := args[first+1:]
	if err := Exec(ctx, p, rest, mgr.Root); err != nil {
		return true, err
	}
	return true, nil
}

// Exec runs the plugin executable with the given args, inheriting stdio and
// injecting ENTIRE_* env vars. The caller's exit code should mirror the
// child's; on a non-zero exit Exec returns an *exec.ExitError so callers can
// inspect ProcessState.
func Exec(ctx context.Context, p *Plugin, args []string, pluginRoot string) error {
	if p == nil {
		return errors.New("plugin: nil plugin")
	}
	if p.ExecPath == "" {
		return fmt.Errorf("plugin %q: missing executable path", p.Name)
	}
	if _, err := os.Stat(p.ExecPath); err != nil {
		return fmt.Errorf("plugin %q: %w", p.Name, err)
	}

	cmd, err := buildExecCommand(ctx, p, args)
	if err != nil {
		return err
	}
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Env = pluginEnv(os.Environ(), p, pluginRoot)
	return cmd.Run()
}

// pluginEnv returns the child environment with ENTIRE_* injections.
//   - ENTIRE_PLUGIN_DATA_DIR: per-plugin durable storage under the plugins root.
//   - ENTIRE_REPO_ROOT: passes through if the parent already set it.
//   - ENTIRE_SESSION_ID: passes through if the parent already set it.
//
// Callers (e.g. main.go) are responsible for setting ENTIRE_REPO_ROOT before
// invoking dispatch. We don't compute it here to avoid pulling the paths
// package and its git CLI dependency into the dispatcher.
func pluginEnv(parent []string, p *Plugin, pluginRoot string) []string {
	out := make([]string, 0, len(parent)+1)
	out = append(out, parent...)
	out = append(out, "ENTIRE_PLUGIN_DATA_DIR="+pluginDataDir(pluginRoot, p.Name))
	return out
}

// pluginDataDir returns a per-plugin data directory adjacent to the plugin
// install location. Plugins should write durable data here, not into the
// install dir (which gets replaced on upgrade).
func pluginDataDir(root, name string) string {
	return root + string(os.PathSeparator) + Prefix + name + string(os.PathSeparator) + "data"
}

// isBuiltin reports whether name resolves to a built-in command or alias on
// rootCmd. This mirrors gh's install-time conflict check.
func isBuiltin(rootCmd *cobra.Command, name string) bool {
	if rootCmd == nil {
		return false
	}
	cmd, _, err := rootCmd.Find([]string{name})
	if err != nil {
		return false
	}
	// Find returns the deepest command it could resolve; for an unknown
	// subcommand it returns rootCmd itself with no error. So a real built-in
	// is anything that resolved past the root.
	return cmd != nil && cmd != rootCmd
}

// PropagateExitCode inspects err for an *exec.ExitError and returns the
// child's exit status, or -1 if err is nil or unrelated to a child exit.
// Callers (typically main.go) can use this to mirror the plugin's exit code.
func PropagateExitCode(err error) int {
	if err == nil {
		return 0
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		return exitErr.ExitCode()
	}
	return -1
}

//go:build unix

package plugin

import (
	"context"
	"os/exec"
)

// buildExecCommand returns an *exec.Cmd that runs the plugin directly. The
// shebang of script plugins is honored by the OS.
func buildExecCommand(ctx context.Context, p *Plugin, args []string) (*exec.Cmd, error) {
	return exec.CommandContext(ctx, p.ExecPath, args...), nil
}

//go:build windows

package plugin

import (
	"context"
	"errors"
	"os/exec"
	"path/filepath"
	"strings"
)

// buildExecCommand returns an *exec.Cmd for the plugin executable.
//
// Binary and local plugins exec directly. Script plugins (git-cloned shell
// scripts) need shebang interpretation, which Windows lacks; we route them
// through sh.exe (gh's approach). The user must have a POSIX sh on PATH —
// Git for Windows ships one.
func buildExecCommand(ctx context.Context, p *Plugin, args []string) (*exec.Cmd, error) {
	if p.Kind == KindScript && !looksExecutable(p.ExecPath) {
		sh, err := exec.LookPath("sh.exe")
		if err != nil {
			return nil, errors.New("script plugins on Windows require sh.exe on PATH (e.g. via Git for Windows)")
		}
		full := append([]string{p.ExecPath}, args...)
		return exec.CommandContext(ctx, sh, full...), nil
	}
	return exec.CommandContext(ctx, p.ExecPath, args...), nil
}

// looksExecutable returns true if the file ends with a Windows-recognized
// executable extension. We use this to decide whether a script plugin entry
// is actually a compiled .exe (run directly) or a shebang script (route
// through sh.exe).
func looksExecutable(path string) bool {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".exe", ".bat", ".cmd", ".com":
		return true
	}
	return false
}

package plugin

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"

	"github.com/spf13/cobra"
)

// InstallLocalOptions configures InstallLocal.
type InstallLocalOptions struct {
	// SourceDir is the directory containing the plugin executable.
	SourceDir string
	// Force replaces any existing plugin entry with the same name.
	Force bool
	// RootCmd is used for built-in conflict detection. Optional; if nil, the
	// check is skipped.
	RootCmd *cobra.Command
}

// InstallLocal symlinks SourceDir into the plugins root as a local plugin.
// Used by `entire plugin install .`. The directory name must be `entire-<name>`
// and must contain an executable of the same name.
func (m *Manager) InstallLocal(opts InstallLocalOptions) (*Plugin, error) {
	src, err := filepath.Abs(opts.SourceDir)
	if err != nil {
		return nil, fmt.Errorf("resolve source dir: %w", err)
	}
	info, err := os.Stat(src)
	if err != nil {
		return nil, fmt.Errorf("stat source dir: %w", err)
	}
	if !info.IsDir() {
		return nil, fmt.Errorf("source must be a directory: %s", src)
	}

	dirName := filepath.Base(src)
	if !strings.HasPrefix(dirName, Prefix) {
		return nil, fmt.Errorf("directory name must start with %q (got %q)", Prefix, dirName)
	}
	bare := strings.TrimPrefix(dirName, Prefix)
	if !ValidName(bare) {
		return nil, fmt.Errorf("invalid plugin name %q", bare)
	}

	exec := filepath.Join(src, executableName(dirName))
	execInfo, err := os.Stat(exec)
	if err != nil {
		return nil, fmt.Errorf("plugin executable %q not found in %s", executableName(dirName), src)
	}
	if runtime.GOOS != "windows" && execInfo.Mode()&0o111 == 0 {
		return nil, fmt.Errorf("plugin executable %s is not executable (chmod +x)", exec)
	}

	if opts.RootCmd != nil && isBuiltin(opts.RootCmd, bare) {
		return nil, fmt.Errorf("name %q conflicts with a built-in command; rename the plugin or use 'entire plugin exec %s' to invoke", bare, bare)
	}

	if err := m.EnsureRoot(); err != nil {
		return nil, err
	}

	dest := filepath.Join(m.Root, dirName)
	if _, err := os.Lstat(dest); err == nil {
		if !opts.Force {
			return nil, fmt.Errorf("plugin %q already installed; use --force to replace", bare)
		}
		if err := os.RemoveAll(dest); err != nil {
			return nil, fmt.Errorf("remove existing plugin: %w", err)
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}

	if err := os.Symlink(src, dest); err != nil {
		return nil, fmt.Errorf("symlink plugin: %w", err)
	}

	return m.Find(bare)
}

package plugin

import (
	"errors"
	"fmt"
	"os"
)

// Remove deletes the plugin with the given bare name. Local plugins (symlinks)
// remove only the symlink, not the source directory. Returns an error if the
// plugin is not installed.
func (m *Manager) Remove(name string) error {
	p, err := m.Find(name)
	if err != nil {
		return err
	}
	if p == nil {
		return fmt.Errorf("plugin %q is not installed", name)
	}

	// Local plugins are symlinks — os.Remove unlinks without touching the
	// target. RemoveAll on a symlink would also just unlink it on Unix, but
	// os.Remove is the right tool for clarity.
	if p.Kind == KindLocal {
		if err := os.Remove(p.Dir); err != nil && !errors.Is(err, os.ErrNotExist) {
			return fmt.Errorf("remove local plugin: %w", err)
		}
		return nil
	}

	if err := os.RemoveAll(p.Dir); err != nil {
		return fmt.Errorf("remove plugin: %w", err)
	}
	return nil
}

package cli

import (
	"errors"
	"fmt"
