func TestValidName(t *testing.T) {
	t.Parallel()
	cases := []struct {
		in   string
		want bool
	}{
		{"foo", true},
		{"foo-bar", true},
		{"foo123", true},
		{"123", true},
		{"", false},
		{"-foo", false},
		{"Foo", false},
