// pathsRefSameFile reports whether src and dest refer to the same filesystem
// object, either by path equality after cleaning or via os.SameFile (handles
// the case where one is a symlink to the other). srcInfo is the FileInfo for
// src that the caller already obtained.
func pathsRefSameFile(src, dest string, srcInfo os.FileInfo) (bool, error) {
	if filepath.Clean(src) == filepath.Clean(dest) {
		return true, nil
	}
	destInfo, err := os.Stat(dest)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return false, nil
		}
		return false, fmt.Errorf("stat install destination: %w", err)
	}
	return os.SameFile(srcInfo, destInfo), nil
}

